using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Handles player input for selecting and placing towers on
/// the spots generated by PlacementSpotGenerator, using a 3D
/// raycast from the mouse cursor.
/// </summary>
public class TowerPlacementManager : MonoBehaviour
{
    [SerializeField] private LayerMask placementSpotLayer;
    [SerializeField] private Camera mainCamera;

    [Header("Click Help")]
    [Tooltip("How close (in pixels at 1080p) the cursor needs to be to a green cube to pick it. Bigger = easier to click")]
    [SerializeField] private float snapRadiusPixels = 35f;

    private GameObject selectedTowerPrefab;

    // True while the player has picked a defender to build and hasn't placed it yet
    public bool IsPlacing => selectedTowerPrefab != null;

    // Fired right after a defender is placed (the upgrade panel listens to this)
    public static event System.Action<Defender> OnDefenderPlaced;
    private PlacementSpot currentHoverSpot;

    private void Awake()
    {
        if (mainCamera == null)
            mainCamera = Camera.main;
    }

    /// <summary>Call this from your UI (e.g. a tower-select button) with the tower prefab to build.</summary>
    public void SelectTowerToBuild(GameObject towerPrefab)
    {
        selectedTowerPrefab = towerPrefab;
    }

    public void CancelSelection()
    {
        selectedTowerPrefab = null;

        if (currentHoverSpot != null)
        {
            currentHoverSpot.SetHover(false);
            currentHoverSpot = null;
        }
    }

    private float freeSpotTimer;

    private void Update()
    {
        // No building while the game is paused
        if (Time.timeScale == 0f)
            return;

        // Twice a second, bring back the green cube of any defender that was destroyed
        freeSpotTimer -= Time.deltaTime;
        if (freeSpotTimer <= 0f)
        {
            freeSpotTimer = 0.5f;
            PlacementSpot.FreeSpotsWithDeadDefenders();
        }

        if (selectedTowerPrefab == null)
            return;

        PlacementSpot spotUnderCursor = GetSpotUnderCursor();

        if (spotUnderCursor != currentHoverSpot)
        {
            if (currentHoverSpot != null)
                currentHoverSpot.SetHover(false);

            currentHoverSpot = spotUnderCursor;

            if (currentHoverSpot != null)
                currentHoverSpot.SetHover(true);
        }

        if (Mouse.current != null && Mouse.current.leftButton.wasPressedThisFrame && currentHoverSpot != null)
        {
            TryBuildOn(currentHoverSpot);
        }

        if (Mouse.current != null && Mouse.current.rightButton.wasPressedThisFrame)
        {
            CancelSelection();
        }
    }

    private PlacementSpot GetSpotUnderCursor()
    {
        if (Mouse.current == null || mainCamera == null)
            return null;

        Vector2 mouse = Mouse.current.position.ReadValue();

        // Scale the pick distance with the screen height so it feels the same at any resolution
        float bestDistance = snapRadiusPixels * (Screen.height / 1080f);
        PlacementSpot best = null;

        foreach (PlacementSpot spot in PlacementSpot.All)
        {
            if (spot == null || spot.IsOccupied) continue;

            Vector3 screenPoint = mainCamera.WorldToScreenPoint(spot.transform.position);

            // Behind the camera
            if (screenPoint.z <= 0f) continue;

            float distance = Vector2.Distance(mouse, new Vector2(screenPoint.x, screenPoint.y));
            if (distance >= bestDistance) continue;

            // Skip spots hidden behind a hill
            if (!IsVisible(spot)) continue;

            bestDistance = distance;
            best = spot;
        }

        return best;
    }

    // True if no terrain is between the camera and the spot
    private bool IsVisible(PlacementSpot spot)
    {
        Vector3 origin = mainCamera.transform.position;
        Vector3 direction = spot.transform.position - origin;
        float distance = direction.magnitude;

        RaycastHit[] hits = Physics.RaycastAll(origin, direction / distance, distance + 0.5f, ~0, QueryTriggerInteraction.Ignore);
        System.Array.Sort(hits, (first, second) => first.distance.CompareTo(second.distance));

        foreach (RaycastHit hit in hits)
        {
            // Walking enemies don't hide a spot
            if (hit.collider.GetComponentInParent<Enemy>() != null) continue;

            PlacementSpot hitSpot = hit.collider.GetComponentInParent<PlacementSpot>();

            if (hitSpot == spot) return true;   // reached the spot itself
            if (hitSpot != null) continue;      // another spot or defender in front, ignore it

            return false;                       // terrain is in the way
        }

        return true;
    }

    private void TryBuildOn(PlacementSpot spot)
    {
        Defender defenderScript = selectedTowerPrefab.GetComponent<Defender>();
        int cost = defenderScript != null ? defenderScript.Cost : 0;

        if(ResourceManager.Instance != null && !ResourceManager.Instance.CanAfford(cost))
        {
            Debug.Log("Not enough resources to build this tower.");
            return;
        }

        if (spot.TryPlaceTower(selectedTowerPrefab, out GameObject tower))
        {
            if (ResourceManager.Instance != null)
            {
                ResourceManager.Instance.TrySpend(cost);
            }
            
            selectedTowerPrefab = null;
            spot.SetHover(false);
            currentHoverSpot = null;

            OnDefenderPlaced?.Invoke(tower.GetComponent<Defender>());
        }
        else
        {
            Debug.Log("That spot is already occupied.");
        }
    }
}